                        Row(
                          children: [
                            Expanded(
                              child: CustomDropdownFormField<int>(
                                items: controller.branchList.map((branch) {
                                  return DropdownMenuItem<int>(
                                    value: branch.branchId,
                                    child: Text(branch.branchName),
