                                }).toList(),
                                initialValue: place!.branchId,
                                onChanged: (value) {
                                  controller.branchId = value;
                                },
                                labelText: 'الفرع',
                                hintText: 'اختر الفرع',
                                prefixIcon: Icons.map,
                                validator: (val) =>
                                    val == null ? 'الرجاء اختيار الفرع' : null,
