                            ),
                            const SizedBox(width: AppDimensions.paddingL),
                            Expanded(
                              child: CustomDropdownFormField<int>(
                                items: controller.areaList.map((area) {
                                  return DropdownMenuItem<int>(
                                    value: area.areaId,
