SizedBox(height: AppDimensions.paddingL,),
                        CustomDropdownFormField<int>(
                          items: controller.placeTypeList.map((placeType) {
                            return DropdownMenuItem<int>(
                              value: placeType.placeTypeId,
                              child: Text(placeType.placeTypeName),
